DO $$ DECLARE t text; safe text; all_cols text; BEGIN FOREACH t IN ARRAY ARRAY['mikrotik_api_credentials','device_credentials','vpn_connections','vpn_clients','notification_settings'] LOOP SELECT string_agg(quote_ident(column_name),',') INTO all_cols FROM information_schema.columns WHERE table_schema='public' AND table_name=t; SELECT string_agg(quote_ident(column_name),',') INTO safe FROM information_schema.columns WHERE table_schema='public' AND table_name=t AND column_name NOT LIKE '%_encrypted' AND column_name NOT LIKE '%_nonce' AND NOT (t='notification_settings' AND column_name='api_token'); EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC,anon,authenticated',t); EXECUTE format('REVOKE SELECT (%s) ON public.%I FROM PUBLIC,anon,authenticated',all_cols,t); EXECUTE format('GRANT SELECT (%s) ON public.%I TO authenticated',safe,t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); END LOOP; END $$;
DROP POLICY IF EXISTS auth_view_vpn_connections ON public.vpn_connections;
REVOKE ALL ON FUNCTION public.purge_old_metric_samples() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_old_metric_samples() TO service_role;
REVOKE ALL ON FUNCTION public.get_vpn_secret(uuid,text), public.get_vpn_client_config(uuid), public.get_device_credential_password(uuid), public.get_mikrotik_api_password(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_vpn_secret(uuid,text), public.get_vpn_client_config(uuid), public.get_device_credential_password(uuid), public.get_mikrotik_api_password(uuid) TO service_role;